@techreport{YIP2023,
  author       = {Yip, Arthur and Hoehne, Christopher and Jadun, Paige and Ledna, Catherine and Hale, Elaine and Muratori, Matteo},
  title        = {Highly Resolved Projections of Passenger Electric Vehicle Charging Loads for the Contiguous United States: Results From and Methods Behind Bottom-Up Simulations of County-Specific Household Electric Vehicle Charging Load (Hourly 8760) Profiles Projected Through 2050 for Differentiated Household and Vehicle Types},
  institution  = {National Renewable Energy Laboratory (NREL), Golden, CO (United States)},
  annote       = {This report documents enhancements made to the TEMPO (Transportation Energy & Mobility Pathway OptionsTM) model to project spatially, demographically, and temporally resolved national-scale EV charging load profiles and describes three scenarios and corresponding datasets created for the NREL demand-side grid (dsgrid) project in support of bulk power systems modeling. In brief, TEMPO was enhanced to disaggregate national and annual energy demand projections into household and county-level projections of passenger electric vehicle (EV) hourly charging load profiles (8760 profiles), accounting for consumer, travel, and temperature variations that impact EV energy demand. In alignment with NREL's forward-looking grid modeling, three scenarios for EV adoption covering 2020-2050 were created--Annual Energy Outlook (AEO) Reference Case, Electrification Futures Study (EFS) High Electrification, and All EV Sales by 2035--and associated datasets have been included in the dsgrid platform for public use.},
  doi          = {10.2172/1984452},
  url          = {https://www.osti.gov/biblio/1984452},
  place        = {United States},
  year         = {2023},
  month        = {06}}

